import { createContext, useContext, useState } from 'react';
import type { ReactNode } from 'react';
import {
  Activity, ArrowUpRight, BriefcaseBusiness, Building2, CalendarCheck, CalendarDays,
  Check, CheckCircle2, ChevronRight, CircleAlert, CircleDollarSign, ClipboardCheck,
  Clock3, Droplets, Eye, FileCheck2, Hammer, Home, LayoutDashboard, LogOut, MapPin,
  Menu, Refrigerator, Search, Settings2, ShieldCheck, Sparkles, Star, TrendingUp,
  UserRound, Users, WalletCards, Wrench, X,
} from 'lucide-react';
import type { LucideIcon } from 'lucide-react';
import { useAuth } from '../store/AuthContext';
import { readDemoState, resetDemoStorage, useDemoState } from '../features/demo/demoStorage';

type Status = 'Pending' | 'In review' | 'Approved' | 'Rejected' | 'Scheduled' | 'Accepted' | 'In progress' | 'Completed' | 'Available' | 'Unavailable' | 'Offline';

const statusStyles: Record<Status, string> = {
  Pending: 'bg-amber-50 text-amber-700 ring-amber-600/20', 'In review': 'bg-violet-50 text-violet-700 ring-violet-600/20',
  Approved: 'bg-emerald-50 text-emerald-700 ring-emerald-600/20', Rejected: 'bg-rose-50 text-rose-700 ring-rose-600/20',
  Scheduled: 'bg-blue-50 text-blue-700 ring-blue-600/20', Accepted: 'bg-indigo-50 text-indigo-700 ring-indigo-600/20',
  'In progress': 'bg-indigo-50 text-indigo-700 ring-indigo-600/20', Completed: 'bg-slate-100 text-slate-600 ring-slate-500/20',
  Available: 'bg-emerald-50 text-emerald-700 ring-emerald-600/20', Unavailable: 'bg-slate-100 text-slate-600 ring-slate-500/20', Offline: 'bg-slate-100 text-slate-500 ring-slate-500/20',
};

const Badge = ({ status }: { status: Status }) => <span className={`inline-flex rounded-full px-2.5 py-1 text-xs font-semibold ring-1 ring-inset ${statusStyles[status]}`}>{status}</span>;

const IconBox = ({ icon: Icon, tone = 'blue' }: { icon: LucideIcon; tone?: 'blue' | 'emerald' | 'amber' | 'violet' | 'slate' }) => {
  const tones = { blue: 'bg-blue-50 text-blue-700', emerald: 'bg-emerald-50 text-emerald-700', amber: 'bg-amber-50 text-amber-700', violet: 'bg-violet-50 text-violet-700', slate: 'bg-slate-100 text-slate-600' };
  return <span className={`flex h-10 w-10 shrink-0 items-center justify-center rounded-lg ${tones[tone]}`}><Icon className="h-5 w-5" /></span>;
};

const SectionHeading = ({ title, subtitle, action }: { title: string; subtitle?: string; action?: ReactNode }) => <div className="mb-4 flex items-end justify-between gap-4"><div><h2 className="text-base font-semibold text-slate-900">{title}</h2>{subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}</div>{action}</div>;

const StatCard = ({ label, value, detail, icon: Icon, tone = 'blue' }: { label: string; value: string; detail: string; icon: LucideIcon; tone?: 'blue' | 'emerald' | 'amber' | 'violet' }) => <div className="border border-slate-200 bg-white p-4 shadow-sm shadow-slate-200/40"><div className="flex items-start justify-between gap-3"><div><p className="text-sm text-slate-500">{label}</p><p className="mt-2 text-2xl font-semibold tracking-tight text-slate-950">{value}</p></div><IconBox icon={Icon} tone={tone} /></div><p className="mt-3 text-xs font-medium text-slate-500">{detail}</p></div>;

const EmptyState = ({ icon: Icon, title, detail }: { icon: LucideIcon; title: string; detail: string }) => <div className="flex flex-col items-center justify-center border border-dashed border-slate-300 bg-slate-50 px-6 py-10 text-center"><Icon className="h-8 w-8 text-slate-400" /><p className="mt-3 text-sm font-semibold text-slate-700">{title}</p><p className="mt-1 max-w-xs text-xs text-slate-500">{detail}</p></div>;

const ActionButton = ({ children, onClick, secondary = false, icon: Icon, disabled = false }: { children: ReactNode; onClick?: () => void; secondary?: boolean; icon?: LucideIcon; disabled?: boolean }) => <button type="button" disabled={disabled} onClick={onClick} className={`inline-flex items-center justify-center gap-2 px-3.5 py-2 text-sm font-semibold transition-colors disabled:cursor-not-allowed disabled:opacity-50 ${secondary ? 'border border-slate-200 bg-white text-slate-700 hover:bg-slate-50 active:bg-slate-100' : 'bg-blue-600 text-white shadow-sm shadow-blue-600/20 hover:bg-blue-700 active:bg-blue-800'}`}>{Icon && <Icon className="h-4 w-4" />}{children}</button>;

const Modal = ({ title, children, onClose, confirmLabel, onConfirm }: { title: string; children: ReactNode; onClose: () => void; confirmLabel?: string; onConfirm?: () => void }) => <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/40 p-4" role="dialog" aria-modal="true"><div className="w-full max-w-lg border border-slate-200 bg-white shadow-2xl"><div className="flex items-center justify-between border-b border-slate-100 px-5 py-4"><h2 className="font-semibold text-slate-950">{title}</h2><button type="button" onClick={onClose} className="text-slate-400 hover:text-slate-700"><X className="h-5 w-5" /></button></div><div className="px-5 py-5 text-sm text-slate-600">{children}</div>{(confirmLabel || onConfirm) && <div className="flex justify-end gap-2 border-t border-slate-100 px-5 py-4"><ActionButton secondary onClick={onClose}>Cancel</ActionButton><ActionButton onClick={onConfirm} icon={Check}>{confirmLabel ?? 'Confirm'}</ActionButton></div>}</div></div>;

const Toast = ({ message, onClose }: { message: string; onClose: () => void }) => <div className="fixed bottom-5 right-5 z-40 flex max-w-sm items-center gap-3 border border-emerald-200 bg-white px-4 py-3 text-sm font-medium text-slate-800 shadow-xl"><CheckCircle2 className="h-5 w-5 shrink-0 text-emerald-600" />{message}<button type="button" onClick={onClose} className="ml-2 text-slate-400 hover:text-slate-700"><X className="h-4 w-4" /></button></div>;

type NavigationContextValue = { active: string; setActive: (section: string) => void };
const NavigationContext = createContext<NavigationContextValue | null>(null);
const isMainSection = (section: string, mainSection: string) => section === mainSection || (section === 'Browse Services' && mainSection === 'Find a service') || (section === 'My Jobs' && mainSection === 'My jobs') || (section === 'Applications' && mainSection === 'Applicants');
const useDashboardNavigation = () => {
  const context = useContext(NavigationContext);
  if (!context) throw new Error('Dashboard navigation must be used inside DashboardShell.');
  return context;
};

const Sidebar = ({ role }: { role: string }) => {
  const { active, setActive } = useDashboardNavigation();
  const links = role === 'CUSTOMER' ? [['Overview', LayoutDashboard], ['Browse Services', Search], ['My Bookings', CalendarDays], ['Activity', Activity]] : role === 'APPLICANT' ? [['Overview', LayoutDashboard], ['My Applications', FileCheck2], ['Opportunities', BriefcaseBusiness], ['Profile / Compliance', ShieldCheck]] : role === 'WORKER' ? [['Overview', LayoutDashboard], ['My Jobs', BriefcaseBusiness], ['Earnings', CircleDollarSign], ['Availability', CalendarDays], ['Profile', UserRound]] : role === 'COOPERATIVE_OFFICER' ? [['Overview', LayoutDashboard], ['Applications', ClipboardCheck], ['Worker Verification', ShieldCheck], ['Cooperative Activity', Activity]] : [['Overview', LayoutDashboard], ['Cooperatives', Building2], ['Workers', Users], ['Applications', ClipboardCheck], ['Activity', Activity]];
  return <aside className="hidden w-64 shrink-0 border-r border-slate-200 bg-white md:flex md:flex-col"><div className="flex h-20 items-center gap-3 border-b border-slate-100 px-6"><div className="flex h-9 w-9 items-center justify-center rounded-lg bg-blue-600 text-white"><Home className="h-5 w-5" /></div><div><p className="text-sm font-bold text-slate-950">Co-op Connect</p><p className="text-[11px] text-slate-500">Marketplace network</p></div></div><nav className="flex-1 space-y-1 px-3 py-6">{links.map(([label, Icon]) => { const IconComponent = Icon as LucideIcon; const isActive = isMainSection(label as string, active); return <button type="button" key={label as string} onClick={() => setActive(label as string)} className={`flex w-full items-center gap-3 px-3 py-2.5 text-left text-sm font-medium transition-colors ${isActive ? 'bg-blue-50 text-blue-700' : 'text-slate-500 hover:bg-slate-50 hover:text-slate-900'}`}><IconComponent className="h-4 w-4" />{label as string}{isActive && <ChevronRight className="ml-auto h-4 w-4" />}</button>; })}</nav><div className="border-t border-slate-100 p-4"><button type="button" onClick={() => setActive('Profile')} className="flex w-full items-center gap-3 px-2 py-2 text-sm text-slate-500 hover:text-slate-900"><Settings2 className="h-4 w-4" />Settings</button></div></aside>;
};

const TopBar = ({ onLogout }: { onLogout: () => void }) => {
  const { profile, session } = useAuth();
  const isDemo = Boolean(session && 'demo' in session && session.demo);
  const reset = () => {
    if (!window.confirm('Reset all local Co-op Connect demo data? This will not affect Supabase.')) return;
    resetDemoStorage();
    window.location.reload();
  };
  return <header className="flex min-h-20 items-center justify-between border-b border-slate-200 bg-white px-4 sm:px-8"><div className="flex items-center gap-3"><button type="button" className="text-slate-500 md:hidden"><Menu className="h-5 w-5" /></button><div><p className="text-sm text-slate-500">Workspace</p><p className="font-semibold text-slate-950">{profile?.role?.replaceAll('_', ' ')}</p></div></div><div className="flex items-center gap-3"><button type="button" className="hidden p-2 text-slate-400 hover:text-slate-700 sm:block"><CircleAlert className="h-5 w-5" /></button>{isDemo && <button type="button" onClick={reset} className="hidden border border-amber-200 bg-amber-50 px-2.5 py-1.5 text-xs font-semibold text-amber-800 hover:bg-amber-100 sm:block">Reset demo data</button>}<div className="hidden h-8 w-px bg-slate-200 sm:block" /><div className="flex items-center gap-2"><div className="flex h-8 w-8 items-center justify-center rounded-full bg-slate-900 text-xs font-semibold text-white">{profile?.name?.charAt(0) ?? 'U'}</div><span className="hidden text-sm font-medium text-slate-700 sm:block">{profile?.name}</span></div><button type="button" onClick={onLogout} className="p-2 text-slate-400 transition-colors hover:text-rose-600" title="Log out"><LogOut className="h-4 w-4" /></button></div></header>;
};

type StoredBooking = { id: number; service: string; worker: string; time: string; area: string; status: Status };
type StoredApplication = { status: Status; applied: string[] };
type StoredJob = { id: number; service: string; customer: string; time: string; area: string; amount: string; status: Status };
type StoredApproval = { id: number; name: string; skill: string; submitted: string; status: Status };

const AvailabilitySection = () => {
  const [available, setAvailable] = useDemoState('cooperative-demo-availability', true);
  return <div className="space-y-6"><SectionHeading title="Availability" subtitle="Control whether new cooperative jobs can be assigned to you." /><div className="border border-slate-200 bg-white p-6 shadow-sm"><div className="flex flex-wrap items-center justify-between gap-4"><div><p className="font-semibold">Job matching status</p><p className="mt-1 text-sm text-slate-500">{available ? 'Customers can request your services.' : 'You will not receive new requests while unavailable.'}</p></div><button type="button" onClick={() => setAvailable((current) => !current)} className={`inline-flex items-center gap-2 border px-4 py-2 text-sm font-semibold ${available ? 'border-emerald-200 bg-emerald-50 text-emerald-700' : 'border-slate-200 bg-slate-50 text-slate-600'}`}><span className={`h-2 w-2 rounded-full ${available ? 'bg-emerald-500' : 'bg-slate-400'}`} />{available ? 'Available' : 'Unavailable'}</button></div></div></div>;
};

const RoleOverview = ({ role, bookings, applicationState, jobs, approvals }: { role: string; bookings: StoredBooking[]; applicationState: StoredApplication; jobs: StoredJob[]; approvals: StoredApproval[] }) => {
  const { profile } = useAuth();
  const completedBookings = bookings.filter((booking) => booking.status === 'Completed').length;
  const activeBookings = bookings.filter((booking) => booking.status !== 'Completed').length;
  const completedJobs = jobs.filter((job) => job.status === 'Completed').length;
  const pendingApprovals = approvals.filter((item) => item.status === 'Pending' || item.status === 'In review').length;
  const approvedApprovals = approvals.filter((item) => item.status === 'Approved').length;
  const rejectedApprovals = approvals.filter((item) => item.status === 'Rejected').length;
  const roleLabel = profile?.role?.replaceAll('_', ' ') ?? role;
  const profileCard = <div className="border border-slate-200 bg-white p-5 shadow-sm"><div className="flex items-center gap-4"><div className="flex h-12 w-12 items-center justify-center rounded-full bg-slate-900 text-sm font-semibold text-white">{profile?.name?.charAt(0) ?? 'U'}</div><div><p className="font-semibold text-slate-950">{profile?.name ?? 'Demo user'}</p><p className="mt-1 text-sm text-slate-500">{profile?.email ?? 'No email available'}</p><p className="mt-2 text-xs font-semibold uppercase tracking-wide text-blue-700">{roleLabel}</p></div></div></div>;
  if (role === 'CUSTOMER') return <div className="space-y-6"><SectionHeading title="Overview" subtitle="Your marketplace activity at a glance." />{profileCard}<div className="grid gap-4 sm:grid-cols-3"><StatCard label="Active / upcoming bookings" value={`${activeBookings}`} detail="Requests still in progress" icon={CalendarCheck} /><StatCard label="Completed bookings" value={`${completedBookings}`} detail="Local demo history" icon={CheckCircle2} tone="emerald" /><StatCard label="Current booking status" value={bookings[0]?.status ?? 'None'} detail={bookings[0]?.service ?? 'Browse services to book'} icon={Clock3} tone="amber" /></div><div className="grid gap-6 lg:grid-cols-2"><div className="border border-slate-200 bg-white p-5 shadow-sm"><SectionHeading title="Recent services" subtitle="Categories already in your activity" /><div className="flex flex-wrap gap-2">{Array.from(new Set(bookings.map((booking) => booking.service))).map((service) => <span key={service} className="bg-slate-100 px-3 py-2 text-xs font-medium text-slate-700">{service}</span>)}</div></div><div className="border border-amber-200 bg-amber-50/60 p-5"><SectionHeading title="What needs your attention" /><p className="text-sm text-slate-700">{bookings.some((booking) => booking.status === 'Pending') ? 'One or more bookings are waiting for worker confirmation.' : 'You are all caught up. Browse services when you need help.'}</p></div></div><div className="border border-slate-200 bg-white p-5 shadow-sm"><SectionHeading title="Recent activity" /><p className="flex gap-3 text-sm"><Activity className="h-4 w-4 text-blue-600" /><span>Plumbing visit completed 2 days ago · {bookings.length} total booking records in this demo.</span></p></div></div>;
  if (role === 'APPLICANT') return <div className="space-y-6"><SectionHeading title="Overview" subtitle="Your application journey and readiness." />{profileCard}<div className="grid gap-4 sm:grid-cols-3"><StatCard label="Application status" value={applicationState.status} detail="Latest application state" icon={ClipboardCheck} tone="amber" /><StatCard label="Applications" value={`${Math.max(applicationState.applied.length, 1)}`} detail="Submitted in this demo" icon={FileCheck2} tone="blue" /><StatCard label="Opportunities" value="2" detail="Matched roles available" icon={BriefcaseBusiness} tone="violet" /></div><div className="grid gap-6 lg:grid-cols-2"><div className="border border-slate-200 bg-white p-5 shadow-sm"><SectionHeading title="Profile & compliance" /><div className="flex justify-between text-sm"><span>Profile completion</span><strong className="text-blue-700">82%</strong></div><div className="mt-2 h-2 bg-slate-100"><div className="h-2 w-[82%] bg-blue-600" /></div><p className="mt-4 text-sm text-slate-600">Identity and skill certificates are verified. Address proof needs attention.</p></div><div className="border border-amber-200 bg-amber-50/60 p-5"><SectionHeading title="What needs your attention" /><p className="text-sm text-slate-700">Complete your address proof to improve application readiness.</p></div></div><div className="border border-slate-200 bg-white p-5 shadow-sm"><SectionHeading title="Recent activity" /><p className="flex gap-3 text-sm"><Activity className="h-4 w-4 text-blue-600" /><span>{applicationState.applied.length ? `Applied to ${applicationState.applied.join(', ')}.` : 'Your application was submitted to Chennai City Labour Cooperative.'}</span></p></div></div>;
  if (role === 'WORKER') { const available = readDemoState<boolean>('cooperative-demo-availability', true); return <div className="space-y-6"><SectionHeading title="Overview" subtitle="Your workday, availability, and earnings." />{profileCard}<div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Availability" value={available ? 'Available' : 'Unavailable'} detail="Job matching status" icon={CalendarDays} tone="emerald" /><StatCard label="Current / upcoming jobs" value={`${jobs.filter((job) => job.status !== 'Completed').length}`} detail="Scheduled in your queue" icon={BriefcaseBusiness} /><StatCard label="Completed jobs" value={`${48 + completedJobs}`} detail="Including demo history" icon={CheckCircle2} tone="violet" /><StatCard label="Earnings" value="₹24,850" detail="April to date · 4.9 rating" icon={CircleDollarSign} tone="amber" /></div><div className="grid gap-6 lg:grid-cols-2"><div className="border border-slate-200 bg-white p-5 shadow-sm"><SectionHeading title="Latest job status" /><p className="flex items-center justify-between text-sm"><span>{jobs[0]?.service ?? 'No jobs yet'}</span>{jobs[0] && <Badge status={jobs[0].status} />}</p></div><div className="border border-amber-200 bg-amber-50/60 p-5"><SectionHeading title="What needs your attention" /><p className="text-sm text-slate-700">{jobs.some((job) => job.status === 'Pending') ? 'Accept the next pending job to keep your schedule current.' : 'Your job queue is up to date.'}</p></div></div><div className="border border-slate-200 bg-white p-5 shadow-sm"><SectionHeading title="Recent activity" /><p className="flex gap-3 text-sm"><Activity className="h-4 w-4 text-blue-600" /><span>{completedJobs ? `${completedJobs} job${completedJobs === 1 ? '' : 's'} completed in this session.` : 'No new completed jobs in this session.'}</span></p></div></div>; }
  if (role === 'COOPERATIVE_OFFICER') return <div className="space-y-6"><SectionHeading title="Overview" subtitle="Your cooperative’s approvals and workforce activity." />{profileCard}<div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Pending applications" value={`${pendingApprovals}`} detail="Need review" icon={ClipboardCheck} tone="amber" /><StatCard label="Approved" value={`${approvedApprovals}`} detail="Worker onboarding" icon={CheckCircle2} tone="emerald" /><StatCard label="Rejected" value={`${rejectedApprovals}`} detail="Resolved applications" icon={X} /><StatCard label="Active workers" value={`${42 + approvedApprovals - 1}`} detail="Cooperative workforce" icon={Users} tone="blue" /></div><div className="grid gap-6 lg:grid-cols-2"><div className="border border-amber-200 bg-amber-50/60 p-5"><SectionHeading title="What needs your attention" /><p className="text-sm text-slate-700">{pendingApprovals ? `${pendingApprovals} applicant${pendingApprovals === 1 ? '' : 's'} waiting for review.` : 'The approval queue is clear.'}</p></div><div className="border border-slate-200 bg-white p-5 shadow-sm"><SectionHeading title="Recent cooperative activity" /><p className="flex gap-3 text-sm"><Activity className="h-4 w-4 text-blue-600" /><span>18 jobs completed today across your cooperative.</span></p></div></div></div>;
  return <div className="space-y-6"><SectionHeading title="Overview" subtitle="Federation-wide performance summary." />{profileCard}<div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Total cooperatives" value="12" detail="Across 4 states" icon={Building2} tone="blue" /><StatCard label="Active workers" value="248" detail="Federation network" icon={Users} tone="emerald" /><StatCard label="Pending applications" value="36" detail="8 need urgent review" icon={ClipboardCheck} tone="amber" /><StatCard label="Completed services" value="1,842" detail="April to date · ₹8.42L revenue" icon={CheckCircle2} tone="violet" /></div><div className="grid gap-6 lg:grid-cols-2"><div className="border border-amber-200 bg-amber-50/60 p-5"><SectionHeading title="What needs attention" /><p className="text-sm text-slate-700">8 applications across the network require urgent review.</p></div><div className="border border-slate-200 bg-white p-5 shadow-sm"><SectionHeading title="Recent federation activity" /><p className="flex gap-3 text-sm"><TrendingUp className="h-4 w-4 text-emerald-600" /><span>Weekly services are up 9.2% across the network.</span></p></div></div></div>;
};

const NavigationSection = ({ role, section }: { role: string; section: string }) => {
  const bookings = readDemoState<StoredBooking[]>('cooperative-demo-bookings', []);
  const applicationState = readDemoState<StoredApplication>('cooperative-demo-applications', { status: 'Pending', applied: [] });
  const jobs = readDemoState<StoredJob[]>('cooperative-demo-jobs', []);
  const approvals = readDemoState<StoredApproval[]>('cooperative-demo-approvals', []);
  const heading = `${section}`;
  if (role === 'WORKER' && section === 'Availability') return <AvailabilitySection />;
  if (section === 'Overview') return <RoleOverview role={role} bookings={bookings} applicationState={applicationState} jobs={jobs} approvals={approvals} />;
  if (role === 'CUSTOMER' && section === 'My Bookings') return <div className="space-y-6"><SectionHeading title="My Bookings" subtitle="Every local service request and its current status." />{bookings.length ? <div className="space-y-3">{bookings.map((booking) => <div key={booking.id} className="flex flex-wrap items-center justify-between gap-4 border border-slate-200 bg-white p-5 shadow-sm"><div><p className="font-semibold">{booking.service}</p><p className="mt-1 text-sm text-slate-500">{booking.worker} · {booking.time} · {booking.area}</p></div><Badge status={booking.status} /></div>)}</div> : <EmptyState icon={CalendarDays} title="No bookings yet" detail="Browse services to create your first local booking." />}</div>;
  if (role === 'CUSTOMER' && section === 'Activity') return <div className="space-y-6"><SectionHeading title="Recent Activity" subtitle="Your latest marketplace activity." /><div className="border border-slate-200 bg-white p-5 shadow-sm"><div className="space-y-4 text-sm"><p className="flex gap-3"><CheckCircle2 className="h-4 w-4 text-emerald-600" /><span><strong>Plumbing visit completed</strong><span className="block text-xs text-slate-500">2 days ago · ₹650 paid</span></span></p><p className="flex gap-3"><CalendarCheck className="h-4 w-4 text-blue-600" /><span><strong>{bookings.length} booking{bookings.length === 1 ? '' : 's'} in your workspace</strong><span className="block text-xs text-slate-500">Synced from local demo state</span></span></p></div></div></div>;
  if (role === 'APPLICANT' && section === 'My Applications') return <div className="space-y-6"><SectionHeading title="My Applications" subtitle="Track applications submitted to cooperative teams." /><div className="border border-slate-200 bg-white p-5 shadow-sm"><div className="flex items-center justify-between"><div><p className="font-semibold">General worker application</p><p className="mt-1 text-sm text-slate-500">Chennai City Labour Cooperative · #APP-2048</p></div><Badge status={applicationState.status} /></div>{applicationState.applied.map((title) => <div key={title} className="mt-4 border-t border-slate-100 pt-4 text-sm"><span className="font-medium">{title}</span><span className="ml-2 text-xs text-emerald-700">Applied</span></div>)}</div></div>;
  if (role === 'APPLICANT' && section === 'Opportunities') return <div className="space-y-6"><SectionHeading title="Opportunities" subtitle="Available roles matched to your profile." /><div className="grid gap-4 md:grid-cols-2">{['Home maintenance specialist', 'Community cleaning crew'].map((title) => <div key={title} className="border border-slate-200 bg-white p-5 shadow-sm"><p className="font-semibold">{title}</p><p className="mt-2 text-sm text-slate-500">Chennai cooperative network · Applications are managed in the main workspace.</p><span className="mt-4 inline-flex text-xs font-semibold text-blue-700">{applicationState.applied.includes(title) ? 'Applied' : 'Open opportunity'}</span></div>)}</div></div>;
  if (role === 'APPLICANT' && section === 'Profile / Compliance') return <div className="space-y-6"><SectionHeading title="Profile & Compliance" subtitle="Your readiness for cooperative work opportunities." /><div className="border border-slate-200 bg-white p-6 shadow-sm"><div className="flex justify-between text-sm"><span className="font-medium">Profile completion</span><span className="font-semibold text-blue-700">82%</span></div><div className="mt-2 h-2 bg-slate-100"><div className="h-2 w-[82%] bg-blue-600" /></div><div className="mt-6 space-y-3 text-sm"><p className="flex justify-between border-t border-slate-100 pt-3">Identity document <span className="text-emerald-700">Verified</span></p><p className="flex justify-between border-t border-slate-100 pt-3">Skill certificates <span className="text-emerald-700">Verified</span></p><p className="flex justify-between border-t border-slate-100 pt-3">Address proof <span className="text-amber-700">Action needed</span></p></div></div></div>;
  if (role === 'WORKER' && section === 'My Jobs') return <div className="space-y-6"><SectionHeading title="My Jobs" subtitle="Your current and upcoming customer visits." /><div className="space-y-3">{jobs.map((job) => <div key={job.id} className="flex flex-wrap items-center justify-between gap-4 border border-slate-200 bg-white p-5 shadow-sm"><div><p className="font-semibold">{job.service}</p><p className="mt-1 text-sm text-slate-500">{job.customer} · {job.time} · {job.area}</p></div><div className="flex items-center gap-3"><span className="text-sm font-semibold">{job.amount}</span><Badge status={job.status} /></div></div>)}</div></div>;
  if (role === 'WORKER' && section === 'Earnings') return <div className="space-y-6"><SectionHeading title="Earnings" subtitle="Your locally simulated cooperative earnings." /><div className="grid gap-4 sm:grid-cols-3"><StatCard label="This month" value="₹24,850" detail="↑ 12% from last month" icon={CircleDollarSign} tone="emerald" /><StatCard label="Completed jobs" value={`${48 + jobs.filter((job) => job.status === 'Completed').length}`} detail="Customer jobs completed" icon={CheckCircle2} tone="violet" /><StatCard label="Rating" value="4.9 / 5" detail="From 48 reviews" icon={Star} tone="amber" /></div></div>;
  if (role === 'WORKER' && section === 'Profile') return <div className="space-y-6"><SectionHeading title="Worker Profile" subtitle="The profile customers see when booking your services." /><div className="border border-slate-200 bg-white p-6 shadow-sm"><p className="text-lg font-semibold">Anil Kumar</p><p className="mt-1 text-sm text-slate-500">Electrical services · Chennai City Labour Cooperative</p><div className="mt-5 grid gap-3 sm:grid-cols-3"><span className="bg-slate-50 p-3 text-sm">4.9 rating</span><span className="bg-slate-50 p-3 text-sm">48 completed jobs</span><span className="bg-slate-50 p-3 text-sm">Chennai service area</span></div></div></div>;
  if (role === 'COOPERATIVE_OFFICER' && section === 'Applications') return <div className="space-y-6"><SectionHeading title="Applications" subtitle="Pending and resolved applications for your cooperative." /><div className="space-y-3">{approvals.map((item) => <div key={item.id} className="flex flex-wrap items-center justify-between gap-4 border border-slate-200 bg-white p-5 shadow-sm"><div><p className="font-semibold">{item.name}</p><p className="mt-1 text-sm text-slate-500">{item.skill} · {item.submitted}</p></div><Badge status={item.status} /></div>)}</div></div>;
  if (role === 'COOPERATIVE_OFFICER' && section === 'Worker Verification') return <div className="space-y-6"><SectionHeading title="Worker Verification" subtitle="Profiles waiting for document review." /><div className="space-y-3">{['Karthik R. · Electrical · 2 documents', 'Muthu S. · Carpentry · 3 documents', 'Divya K. · Cleaning · 2 documents'].map((item) => <div key={item} className="flex items-center justify-between border border-slate-200 bg-white p-5 shadow-sm"><span className="text-sm font-medium">{item}</span><Badge status="Pending" /></div>)}</div></div>;
  if (role === 'COOPERATIVE_OFFICER' && section === 'Cooperative Activity') return <div className="space-y-6"><SectionHeading title="Cooperative Activity" subtitle="Recent actions across your cooperative." /><div className="border border-slate-200 bg-white p-5 shadow-sm"><p className="flex gap-3 text-sm"><Activity className="h-4 w-4 text-blue-600" /><span><strong>18 jobs completed today</strong><span className="block text-xs text-slate-500">Across Chennai City Labour Cooperative</span></span></p></div></div>;
  if (role === 'FEDERATION_ADMIN' && section === 'Cooperatives') return <div className="space-y-6"><SectionHeading title="Cooperatives" subtitle="Federation-wide cooperative management." /><div className="border border-slate-200 bg-white p-5 shadow-sm"><p className="font-semibold">12 registered cooperatives</p><p className="mt-2 text-sm text-slate-500">Use the main overview table to open cooperative details and review network performance.</p></div></div>;
  if (role === 'FEDERATION_ADMIN' && section === 'Workers') return <div className="space-y-6"><SectionHeading title="Workers" subtitle="Network workforce statistics." /><div className="grid gap-4 sm:grid-cols-3"><StatCard label="Active workers" value="248" detail="Across 12 cooperatives" icon={Users} tone="emerald" /><StatCard label="Available today" value="201" detail="Ready for service requests" icon={CheckCircle2} tone="blue" /><StatCard label="Average rating" value="4.7 / 5" detail="Federation-wide" icon={Star} tone="amber" /></div></div>;
  if (role === 'FEDERATION_ADMIN' && section === 'Applications') return <div className="space-y-6"><SectionHeading title="Applications" subtitle="Federation-wide approval pipeline." /><div className="grid gap-4 sm:grid-cols-3"><StatCard label="Pending" value="36" detail="Need cooperative review" icon={ClipboardCheck} tone="amber" /><StatCard label="Approved this month" value="84" detail="New workers onboarded" icon={CheckCircle2} tone="emerald" /><StatCard label="Review time" value="2.4 days" detail="Average processing time" icon={Clock3} tone="blue" /></div></div>;
  if (role === 'FEDERATION_ADMIN' && section === 'Activity') return <div className="space-y-6"><SectionHeading title="Federation Activity" subtitle="Recent system activity across the network." /><div className="border border-slate-200 bg-white p-5 shadow-sm"><div className="space-y-4 text-sm"><p className="flex gap-3"><Building2 className="h-4 w-4 text-blue-600" /><span><strong>New cooperative registered</strong><span className="block text-xs text-slate-500">Madurai Services Cooperative · 3h ago</span></span></p><p className="flex gap-3"><TrendingUp className="h-4 w-4 text-emerald-600" /><span><strong>Weekly services up 9.2%</strong><span className="block text-xs text-slate-500">Network performance · Yesterday</span></span></p></div></div></div>;
  return <div className="space-y-6"><SectionHeading title={heading} subtitle="This dashboard section is ready for the local demo." /><EmptyState icon={LayoutDashboard} title="No additional records" detail="Use the main workspace actions to create local demo activity." /></div>;
};

const DashboardShell = ({ children, active, title, intro }: { children: ReactNode; active: string; title: string; intro: string }) => {
  const { profile, signOut } = useAuth();
  const [activeSection, setActiveSection] = useState(active);
  const content = isMainSection(activeSection, active) ? children : <NavigationSection role={profile?.role ?? ''} section={activeSection} />;
  return <NavigationContext.Provider value={{ active: activeSection, setActive: setActiveSection }}><div className="min-h-screen bg-slate-50 text-slate-900"><div className="flex min-h-screen"><Sidebar role={profile?.role ?? ''} /><div className="min-w-0 flex-1"><TopBar onLogout={signOut} /><main className="mx-auto max-w-[1440px] px-4 py-7 sm:px-8"><div className="mb-7"><p className="mb-2 text-sm font-medium text-blue-600">{title}</p><h1 className="text-2xl font-semibold tracking-tight text-slate-950 sm:text-3xl">{intro}</h1></div>{content}</main></div></div></div></NavigationContext.Provider>;
};

const CustomerDashboard = () => {
  const [query, setQuery] = useState(''); const [notice, setNotice] = useState<string | null>(null); const [selected, setSelected] = useState<{ name: string; service: string } | null>(null); const [showAll, setShowAll] = useState(false);
  const [bookings, setBookings] = useDemoState('cooperative-demo-bookings', [{ id: 1, service: 'Electrical inspection', worker: 'Anil Kumar', time: 'Tomorrow · 10:00 AM', area: 'T. Nagar', status: 'Scheduled' as Status }, { id: 2, service: 'Kitchen deep clean', worker: 'Meera S.', time: 'Fri, 18 Apr · 2:30 PM', area: 'Adyar', status: 'Pending' as Status }]);
  const workers = [{ name: 'Anil Kumar', service: 'Electrical Repair', rating: '4.9', area: 'T. Nagar', availability: 'Available' as Status, initials: 'AK', tone: 'bg-blue-100 text-blue-700' }, { name: 'Meera S.', service: 'Home Cleaning', rating: '4.8', area: 'Adyar', availability: 'Available' as Status, initials: 'MS', tone: 'bg-violet-100 text-violet-700' }, { name: 'Ravi Prakash', service: 'Plumbing', rating: '4.7', area: 'Anna Nagar', availability: 'Offline' as Status, initials: 'RP', tone: 'bg-amber-100 text-amber-700' }];
  const categories = [{ label: 'Electrical Repair', icon: Wrench, tone: 'blue' as const }, { label: 'Plumbing', icon: Droplets, tone: 'emerald' as const }, { label: 'Home Cleaning', icon: Sparkles, tone: 'violet' as const }, { label: 'Appliance Repair', icon: Refrigerator, tone: 'amber' as const }, { label: 'Carpentry', icon: Hammer, tone: 'slate' as const }];
  const filtered = workers.filter((worker) => `${worker.name} ${worker.service} ${worker.area}`.toLowerCase().includes(query.toLowerCase()));
  const confirmBooking = () => { if (!selected) return; setBookings((current) => [...current, { id: Date.now(), service: selected.service, worker: selected.name, time: 'Next available · 2:00 PM', area: 'Chennai', status: 'Pending' }]); setNotice(`Request sent to ${selected.name}. Your booking is pending confirmation.`); setSelected(null); };
  return <DashboardShell active="Find a service" title="Customer workspace" intro="Find trusted help, right in your neighborhood.">{notice && <Toast message={notice} onClose={() => setNotice(null)} />}<div className="mb-8 flex flex-col gap-4 border border-blue-100 bg-blue-50/70 p-5 sm:flex-row sm:items-center sm:justify-between"><div><p className="text-sm font-medium text-blue-700">Need a hand?</p><p className="mt-1 text-lg font-semibold text-slate-950">Book a verified cooperative worker in minutes.</p></div><ActionButton icon={Search} onClick={() => document.getElementById('worker-search')?.focus()}>Browse services</ActionButton></div><div className="mb-8 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Upcoming bookings" value={`${bookings.length}`} detail="Your next local visits" icon={CalendarCheck} /><StatCard label="Services completed" value="12" detail="Across 3 service categories" icon={CheckCircle2} tone="emerald" /><StatCard label="Saved workers" value="4" detail="Your trusted local network" icon={Star} tone="amber" /><StatCard label="Co-op member benefit" value="5%" detail="Applied to eligible bookings" icon={WalletCards} tone="violet" /></div><div className="grid gap-8 xl:grid-cols-[1fr_320px]"><div><SectionHeading title="Browse categories" subtitle="Select a category to filter nearby workers" /><div className="mb-8 grid grid-cols-2 gap-3 md:grid-cols-3 xl:grid-cols-5">{categories.map(({ label, icon, tone }) => <button type="button" key={label} onClick={() => setQuery(query === label ? '' : label)} className={`group border p-4 text-left shadow-sm transition hover:border-blue-200 hover:shadow-md ${query === label ? 'border-blue-400 bg-blue-50' : 'border-slate-200 bg-white'}`}><IconBox icon={icon} tone={tone} /><p className="mt-3 text-sm font-semibold text-slate-800">{label}</p><p className="mt-1 text-xs text-slate-500">From ₹400</p></button>)}</div><SectionHeading title="Available near you" subtitle="Trusted workers in Chennai" action={<div className="relative"><Search className="absolute left-3 top-2.5 h-4 w-4 text-slate-400" /><input id="worker-search" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search workers or services" className="w-full border border-slate-200 bg-white py-2 pl-9 pr-3 text-sm outline-none ring-blue-500 focus:ring-2 sm:w-64" /></div>} /><div className="grid gap-4 lg:grid-cols-3">{filtered.map((worker) => <div key={worker.name} className="border border-slate-200 bg-white p-5 shadow-sm"><div className="flex items-start justify-between"><div className={`flex h-11 w-11 items-center justify-center rounded-full text-sm font-bold ${worker.tone}`}>{worker.initials}</div><Badge status={worker.availability} /></div><h3 className="mt-4 font-semibold">{worker.name}</h3><p className="mt-1 text-sm text-blue-700">{worker.service}</p><div className="mt-4 space-y-2 text-xs text-slate-500"><span className="flex items-center gap-2"><Star className="h-3.5 w-3.5 fill-amber-400 text-amber-400" />{worker.rating} rating <span className="text-slate-300">•</span> 48 jobs</span><span className="flex items-center gap-2"><MapPin className="h-3.5 w-3.5" />{worker.area}, Chennai</span></div><ActionButton onClick={() => setSelected({ name: worker.name, service: worker.service })}>{worker.availability === 'Available' ? 'Book worker' : 'Request service'}</ActionButton></div>)}{filtered.length === 0 && <div className="lg:col-span-3"><EmptyState icon={Search} title="No matching workers" detail="Try another service or area." /></div>}</div></div><div><SectionHeading title="Upcoming bookings" action={<button type="button" onClick={() => setShowAll((current) => !current)} className="text-xs font-semibold text-blue-600 hover:text-blue-700">{showAll ? 'Show less' : 'View all'}</button>} /><div className="space-y-3">{bookings.slice(0, showAll ? bookings.length : 2).map((booking) => <div key={booking.id} className="border border-slate-200 bg-white p-4 shadow-sm"><div className="flex justify-between gap-3"><div><p className="text-sm font-semibold">{booking.service}</p><p className="mt-1 text-xs text-slate-500">{booking.time}</p></div><Badge status={booking.status} /></div><p className="mt-3 flex items-center gap-1.5 text-xs text-slate-500"><MapPin className="h-3.5 w-3.5" />{booking.area} · {booking.worker}</p></div>)}</div><SectionHeading title="Recent activity" /><div className="border border-slate-200 bg-white p-4 shadow-sm"><p className="flex gap-3 text-sm"><CheckCircle2 className="h-4 w-4 shrink-0 text-emerald-600" /><span><strong>Plumbing visit completed</strong><span className="block text-xs text-slate-500">2 days ago · ₹650 paid</span></span></p></div></div></div>{selected && <Modal title="Confirm service request" onClose={() => setSelected(null)} confirmLabel="Confirm booking" onConfirm={confirmBooking}><p>You are requesting <strong>{selected.service}</strong> from <strong>{selected.name}</strong>.</p><p className="mt-3 flex items-center gap-2 text-xs text-slate-500"><Clock3 className="h-4 w-4" />Next available visit · Today at 2:00 PM</p></Modal>}</DashboardShell>;
};

const ApplicantDashboard = () => {
  const [notice, setNotice] = useState<string | null>(null); const [applicationState, setApplicationState] = useDemoState('cooperative-demo-applications', { status: 'Pending' as Status, applied: [] as string[] }); const [detailsOpen, setDetailsOpen] = useState(false);
  const { status: applicationStatus, applied } = applicationState;
  const opportunities = [{ title: 'Home maintenance specialist', coop: 'Chennai City Labour Cooperative', area: 'T. Nagar', pay: '₹18,000–24,000 / month', icon: Wrench }, { title: 'Community cleaning crew', coop: 'South Chennai Workers Federation', area: 'Adyar', pay: '₹15,000–20,000 / month', icon: Sparkles }];
  const apply = (title: string) => { setApplicationState((current) => ({ status: 'In review', applied: current.applied.includes(title) ? current.applied : [...current.applied, title] })); setNotice(`Application submitted for ${title}.`); };
  return <DashboardShell active="Opportunities" title="Applicant workspace" intro="Build your next opportunity with the cooperative network.">{notice && <Toast message={notice} onClose={() => setNotice(null)} />}{detailsOpen && <Modal title="Application details" onClose={() => setDetailsOpen(false)}><p>Your application is being reviewed by the cooperative team. You will be notified when a decision is made.</p><p className="mt-3 text-xs text-slate-500">Reference #APP-2048 · Submitted 3 days ago</p></Modal>}<div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Application status" value={applicationStatus} detail="Updated just now" icon={ClipboardCheck} tone="amber" /><StatCard label="Profile completion" value="82%" detail="Add one certification to finish" icon={UserRound} tone="blue" /><StatCard label="Opportunities" value="8" detail="Matched to your skills" icon={BriefcaseBusiness} tone="violet" /><StatCard label="Documents verified" value="4 / 5" detail="Awaiting address proof" icon={ShieldCheck} tone="emerald" /></div><div className="mt-8 grid gap-8 xl:grid-cols-[1.1fr_0.9fr]"><div><SectionHeading title="Your application" subtitle="Chennai cooperative worker program" /><div className="border border-slate-200 bg-white p-5 shadow-sm"><div className="flex flex-wrap items-start justify-between gap-4"><div><p className="font-semibold">General worker application</p><p className="mt-1 text-sm text-slate-500">Chennai City Labour Cooperative</p></div><Badge status={applicationStatus} /></div><div className="mt-7 grid grid-cols-3 gap-2"><div><div className="h-1 bg-blue-600" /><div className="mt-2 text-xs font-semibold text-blue-700">Submitted</div></div><div><div className={`h-1 ${applicationStatus === 'Pending' ? 'bg-slate-200' : 'bg-blue-600'}`} /><div className="mt-2 text-xs font-semibold text-slate-500">Under review</div></div><div><div className="h-1 bg-slate-200" /><div className="mt-2 text-xs font-semibold text-slate-500">Decision</div></div></div><div className="mt-6 flex items-center justify-between border-t border-slate-100 pt-4 text-xs text-slate-500"><span>Reference #APP-2048</span><button type="button" onClick={() => setDetailsOpen(true)} className="font-semibold text-blue-600 hover:text-blue-700">View details</button></div></div><SectionHeading title="Recent applications" subtitle="Your latest activity" /><div className="divide-y divide-slate-100 border border-slate-200 bg-white shadow-sm"><div className="flex items-center justify-between gap-4 p-4"><div><p className="text-sm font-semibold">General worker application</p><p className="mt-1 text-xs text-slate-500">Chennai City Labour Cooperative · just now</p></div><Badge status={applicationStatus} /></div></div></div><div><SectionHeading title="Profile & compliance" /><div className="border border-slate-200 bg-white p-5 shadow-sm"><div><div className="flex justify-between text-sm"><span className="font-medium">Profile completion</span><span className="font-semibold text-blue-700">82%</span></div><div className="mt-2 h-2 bg-slate-100"><div className="h-2 w-[82%] bg-blue-600" /></div></div>{['Identity document', 'Skill certificates', 'Address proof'].map((item, index) => <div key={item} className="flex items-center justify-between border-t border-slate-100 pt-3 mt-4 text-sm"><span className="text-slate-600">{item}</span>{index < 2 ? <span className="flex items-center gap-1.5 text-xs font-semibold text-emerald-700"><CheckCircle2 className="h-4 w-4" />Verified</span> : <span className="text-xs font-semibold text-amber-700">Action needed</span>}</div>)}<ActionButton secondary icon={FileCheck2} onClick={() => setNotice('Document checklist opened. Address proof is the next item to upload.')}>Manage documents</ActionButton></div><SectionHeading title="Matched opportunities" /><div className="space-y-3">{opportunities.map((opportunity) => { const isApplied = applied.includes(opportunity.title); return <div key={opportunity.title} className="border border-slate-200 bg-white p-4 shadow-sm"><div className="flex gap-3"><IconBox icon={opportunity.icon} tone="blue" /><div className="min-w-0 flex-1"><div className="flex flex-wrap justify-between gap-2"><p className="text-sm font-semibold">{opportunity.title}</p><span className="text-xs font-semibold text-emerald-700">{opportunity.pay}</span></div><p className="mt-1 text-xs text-slate-500">{opportunity.coop} · {opportunity.area}</p><button type="button" disabled={isApplied} onClick={() => apply(opportunity.title)} className={`mt-3 text-xs font-semibold ${isApplied ? 'cursor-default text-emerald-700' : 'text-blue-600 hover:text-blue-700'}`}>{isApplied ? 'Applied' : 'Apply now'} {!isApplied && <ArrowUpRight className="ml-1 inline h-3.5 w-3.5" />}</button></div></div></div>; })}</div></div></div></DashboardShell>;
};

type Job = { id: number; service: string; customer: string; time: string; area: string; amount: string; status: Status };
const WorkerDashboard = () => {
  const [available, setAvailable] = useDemoState('cooperative-demo-availability', true); const [notice, setNotice] = useState<string | null>(null); const [jobs, setJobs] = useDemoState<Job[]>('cooperative-demo-jobs', [{ id: 1, service: 'Electrical inspection', customer: 'S. Narayanan', time: 'Today · 10:00 AM', area: 'T. Nagar', amount: '₹850', status: 'Scheduled' }, { id: 2, service: 'Ceiling fan repair', customer: 'Kavya R.', time: 'Today · 3:30 PM', area: 'Adyar', amount: '₹650', status: 'Pending' }, { id: 3, service: 'Wiring replacement', customer: 'Arun M.', time: 'Tomorrow · 11:00 AM', area: 'Velachery', amount: '₹1,200', status: 'Scheduled' }]);
  const updateJob = (id: number, status: Status) => { const job = jobs.find((item) => item.id === id); setJobs((current) => current.map((item) => item.id === id ? { ...item, status } : item)); if (job) setNotice(`${job.service} is now ${status.toLowerCase()}.`); };
  const completed = jobs.filter((job) => job.status === 'Completed').length;
  return <DashboardShell active="My jobs" title="Worker workspace" intro="Good morning, Anil. Here is your workday at a glance.">{notice && <Toast message={notice} onClose={() => setNotice(null)} />}<div className="mb-8 flex flex-col gap-4 border border-slate-200 bg-white p-5 shadow-sm sm:flex-row sm:items-center sm:justify-between"><div className="flex items-center gap-3"><div className="flex h-12 w-12 items-center justify-center rounded-full bg-blue-100 text-sm font-bold text-blue-700">AK</div><div><p className="font-semibold">Anil Kumar</p><p className="text-sm text-slate-500">Electrical services · Chennai City Labour Cooperative</p></div></div><button type="button" onClick={() => { setAvailable((current) => !current); setNotice(`You are now ${available ? 'unavailable' : 'available'} for new jobs.`); }} className={`inline-flex items-center gap-2 border px-3.5 py-2 text-sm font-semibold ${available ? 'border-emerald-200 bg-emerald-50 text-emerald-700' : 'border-slate-200 bg-slate-50 text-slate-600'}`}><span className={`h-2 w-2 rounded-full ${available ? 'bg-emerald-500' : 'bg-slate-400'}`} />{available ? 'Available' : 'Unavailable'}</button></div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Today's jobs" value={`${jobs.filter((job) => job.time.startsWith('Today')).length}`} detail="Your scheduled visits" icon={CalendarCheck} /><StatCard label="This month" value="₹24,850" detail="↑ 12% from last month" icon={CircleDollarSign} tone="emerald" /><StatCard label="Customer rating" value="4.9 / 5" detail="From 48 completed jobs" icon={Star} tone="amber" /><StatCard label="Completed jobs" value={`${48 + completed}`} detail="Keep up the great work" icon={CheckCircle2} tone="violet" /></div><div className="mt-8 grid gap-8 xl:grid-cols-[1.15fr_0.85fr]"><div><SectionHeading title="Today's jobs" subtitle="Accept work and keep customers updated" /><div className="space-y-3">{jobs.filter((job) => job.time.startsWith('Today')).map((job) => <div key={job.id} className="border border-slate-200 bg-white p-4 shadow-sm"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="font-semibold">{job.service}</p><p className="mt-1 text-sm text-slate-500">{job.customer} · {job.area}</p></div><Badge status={job.status} /></div><div className="mt-4 flex flex-wrap items-center justify-between gap-3 border-t border-slate-100 pt-3"><span className="flex items-center gap-2 text-xs font-medium text-slate-500"><Clock3 className="h-4 w-4" />{job.time}</span><div className="flex gap-2">{job.status === 'Pending' && <ActionButton onClick={() => updateJob(job.id, 'Accepted')} icon={Check}>Accept job</ActionButton>}{(job.status === 'Accepted' || job.status === 'Scheduled') && <ActionButton secondary onClick={() => updateJob(job.id, 'Completed')}>Mark complete</ActionButton>}{job.status === 'Completed' && <span className="text-xs font-semibold text-emerald-700">Payment released</span>}</div></div></div>)}</div><SectionHeading title="Upcoming jobs" subtitle="Your next scheduled visits" /><div className="border border-slate-200 bg-white shadow-sm"><div className="flex items-center justify-between p-4"><div><p className="text-sm font-semibold">Wiring replacement</p><p className="mt-1 text-xs text-slate-500">Tomorrow · 11:00 AM · Velachery</p></div><span className="text-sm font-semibold">₹1,200</span></div></div></div><div><SectionHeading title="Earnings overview" /><div className="border border-slate-200 bg-white p-5 shadow-sm"><div className="flex items-center justify-between"><div><p className="text-3xl font-semibold tracking-tight">₹24,850</p><p className="mt-1 text-xs text-slate-500">April earnings</p></div><span className="flex items-center gap-1 text-xs font-semibold text-emerald-700"><TrendingUp className="h-4 w-4" />12.4%</span></div><div className="mt-7 flex h-24 items-end gap-2">{[35, 48, 42, 58, 52, 70, 64, 82, 76, 92].map((height, index) => <div key={index} className={`flex-1 ${index === 9 ? 'bg-blue-600' : 'bg-blue-100'}`} style={{ height: `${height}%` }} />)}</div></div></div></div></DashboardShell>;
};

type Applicant = { id: number; name: string; skill: string; submitted: string; status: Status };
const CoopOfficerDashboard = () => {
  const [notice, setNotice] = useState<string | null>(null); const [selected, setSelected] = useState<Applicant | null>(null); const [applicants, setApplicants] = useDemoState<Applicant[]>('cooperative-demo-approvals', [{ id: 1, name: 'Rahul Menon', skill: 'Plumbing & maintenance', submitted: 'Today, 9:40 AM', status: 'Pending' }, { id: 2, name: 'Divya Krishnan', skill: 'Home cleaning', submitted: 'Yesterday', status: 'In review' }, { id: 3, name: 'Sanjay Babu', skill: 'Electrical repair', submitted: 'Apr 12', status: 'Approved' }]);
  const decide = (id: number, status: Status) => { const item = applicants.find((applicant) => applicant.id === id); setApplicants((current) => current.map((applicant) => applicant.id === id ? { ...applicant, status } : applicant)); setSelected(null); if (item) setNotice(`${item.name} marked ${status.toLowerCase()}.`); };
  const pending = applicants.filter((item) => item.status === 'Pending' || item.status === 'In review');
  return <DashboardShell active="Applicants" title="Cooperative workspace" intro="Keep your cooperative moving forward.">{notice && <Toast message={notice} onClose={() => setNotice(null)} />}<div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Pending approvals" value={`${pending.length}`} detail="Applications needing action" icon={ClipboardCheck} tone="amber" /><StatCard label="Active workers" value={`${42 + applicants.filter((item) => item.status === 'Approved').length - 1}`} detail="38 available today" icon={Users} tone="emerald" /><StatCard label="Jobs this month" value="286" detail="↑ 18% vs March" icon={CalendarCheck} tone="blue" /><StatCard label="Co-op earnings" value="₹1.84L" detail="April to date" icon={CircleDollarSign} tone="violet" /></div><div className="mt-8 grid gap-8 xl:grid-cols-[1.15fr_0.85fr]"><div><SectionHeading title="Applicant approvals" subtitle="Review new applications for Chennai City Labour Cooperative" /><div className="space-y-3">{pending.length === 0 ? <EmptyState icon={CheckCircle2} title="Queue is clear" detail="All applications have been reviewed." /> : pending.map((applicant) => <div key={applicant.id} className="border border-slate-200 bg-white p-4 shadow-sm"><div className="flex flex-wrap items-start justify-between gap-3"><div className="flex gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-full bg-slate-100 text-sm font-semibold text-slate-600">{applicant.name.split(' ').map((part) => part[0]).join('')}</div><div><p className="text-sm font-semibold">{applicant.name}</p><p className="mt-1 text-xs text-slate-500">{applicant.skill} · Submitted {applicant.submitted}</p></div></div><Badge status={applicant.status} /></div><div className="mt-4 flex gap-2 border-t border-slate-100 pt-3"><ActionButton secondary icon={Eye} onClick={() => setSelected(applicant)}>Review profile</ActionButton><ActionButton onClick={() => decide(applicant.id, 'Approved')} icon={Check}>Approve</ActionButton><button type="button" onClick={() => decide(applicant.id, 'Rejected')} className="px-3 text-sm font-semibold text-rose-600 hover:text-rose-700">Reject</button></div></div>)}</div></div><div><SectionHeading title="Worker verification queue" /><div className="border border-slate-200 bg-white shadow-sm"><div className="flex items-center gap-3 border-b border-slate-100 p-4"><IconBox icon={ShieldCheck} tone="amber" /><div className="flex-1"><p className="text-sm font-semibold">3 profiles need verification</p><p className="mt-1 text-xs text-slate-500">Documents are ready for review</p></div><ChevronRight className="h-4 w-4 text-slate-400" /></div>{['Karthik R. · Electrical', 'Muthu S. · Carpentry'].map((worker) => <div key={worker} className="flex items-center justify-between border-b border-slate-100 p-4 last:border-0"><p className="text-sm font-medium">{worker}</p><button type="button" onClick={() => setNotice(`Verification details opened for ${worker.split(' · ')[0]}.`)} className="text-xs font-semibold text-blue-600">Review</button></div>)}</div><SectionHeading title="Recent cooperative activity" /><div className="border border-slate-200 bg-white p-4 shadow-sm"><p className="flex gap-3 text-sm"><Activity className="h-4 w-4 shrink-0 text-blue-600" /><span><strong>18 jobs completed</strong><span className="block text-xs text-slate-500">Across your cooperative today</span></span></p></div></div></div>{selected && <Modal title={`Review ${selected.name}`} onClose={() => setSelected(null)}><p className="font-semibold text-slate-900">{selected.skill}</p><p className="mt-2">Application received {selected.submitted}. Identity and skill documents are ready for your review.</p><div className="mt-4 flex gap-2"><ActionButton onClick={() => decide(selected.id, 'Approved')} icon={Check}>Approve applicant</ActionButton><ActionButton secondary onClick={() => decide(selected.id, 'Rejected')}>Reject</ActionButton></div></Modal>}</DashboardShell>;
};

const FedAdminDashboard = () => {
  const [notice, setNotice] = useState<string | null>(null); const [selected, setSelected] = useState<{ name: string; location: string; workers: number; jobs: number; status: Status } | null>(null); const [showAdd, setShowAdd] = useState(false);
  const cooperatives = [{ name: 'Chennai City Labour Cooperative', location: 'Chennai, Tamil Nadu', workers: 42, jobs: 286, status: 'Available' as Status }, { name: 'South Chennai Workers Federation', location: 'Chennai, Tamil Nadu', workers: 28, jobs: 174, status: 'Available' as Status }, { name: 'Madurai Services Cooperative', location: 'Madurai, Tamil Nadu', workers: 19, jobs: 98, status: 'Offline' as Status }];
  return <DashboardShell active="Cooperatives" title="Federation overview" intro="A clear view of the cooperative network.">{notice && <Toast message={notice} onClose={() => setNotice(null)} />}{showAdd && <Modal title="Register a cooperative" onClose={() => setShowAdd(false)} confirmLabel="Save draft" onConfirm={() => { setShowAdd(false); setNotice('Cooperative registration draft saved locally.'); }}><p>This demo action saves a local draft only. No Supabase data will be changed.</p><div className="mt-4 space-y-3"><input placeholder="Cooperative name" className="w-full border border-slate-200 px-3 py-2 text-sm" /><input placeholder="City and state" className="w-full border border-slate-200 px-3 py-2 text-sm" /></div></Modal>}{selected && <Modal title={selected.name} onClose={() => setSelected(null)}><p className="text-sm text-slate-500">{selected.location}</p><div className="mt-5 grid grid-cols-2 gap-3"><div className="bg-slate-50 p-3"><p className="text-xs text-slate-500">Active workers</p><p className="mt-1 text-xl font-semibold">{selected.workers}</p></div><div className="bg-slate-50 p-3"><p className="text-xs text-slate-500">Completed jobs</p><p className="mt-1 text-xl font-semibold">{selected.jobs}</p></div></div><p className="mt-4 text-sm">Status: <Badge status={selected.status} /></p></Modal>}<div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Total cooperatives" value="12" detail="Across 4 states" icon={Building2} tone="blue" /><StatCard label="Active workers" value="248" detail="↑ 9.2% this quarter" icon={Users} tone="emerald" /><StatCard label="Pending applications" value="36" detail="8 require urgent review" icon={ClipboardCheck} tone="amber" /><StatCard label="Completed services" value="1,842" detail="April to date" icon={CheckCircle2} tone="violet" /></div><div className="mt-8 grid gap-8 xl:grid-cols-[1.2fr_0.8fr]"><div><SectionHeading title="Cooperative network" subtitle="Performance across registered cooperatives" action={<ActionButton secondary icon={Building2} onClick={() => setShowAdd(true)}>Add cooperative</ActionButton>} /><div className="overflow-hidden border border-slate-200 bg-white shadow-sm"><div className="hidden grid-cols-[1.5fr_0.7fr_0.7fr_0.7fr] gap-4 border-b border-slate-100 bg-slate-50 px-4 py-3 text-xs font-semibold uppercase tracking-wide text-slate-500 sm:grid"><span>Cooperative</span><span>Workers</span><span>Jobs</span><span>Status</span></div>{cooperatives.map((coop) => <button type="button" key={coop.name} onClick={() => setSelected(coop)} className="grid w-full gap-3 border-b border-slate-100 px-4 py-4 text-left transition hover:bg-slate-50 last:border-0 sm:grid-cols-[1.5fr_0.7fr_0.7fr_0.7fr] sm:items-center sm:gap-4"><div><p className="text-sm font-semibold text-slate-900">{coop.name}</p><p className="mt-1 flex items-center gap-1 text-xs text-slate-500"><MapPin className="h-3 w-3" />{coop.location}</p></div><div><span className="text-xs text-slate-400 sm:hidden">Workers </span><span className="text-sm font-semibold">{coop.workers}</span></div><div><span className="text-xs text-slate-400 sm:hidden">Jobs </span><span className="text-sm font-semibold">{coop.jobs}</span></div><div><Badge status={coop.status} /></div></button>)}</div></div><div><SectionHeading title="Activity & revenue" /><div className="border border-slate-200 bg-white p-5 shadow-sm"><div className="flex items-center justify-between"><div><p className="text-3xl font-semibold tracking-tight">₹8.42L</p><p className="mt-1 text-xs text-slate-500">Network revenue this month</p></div><span className="flex items-center gap-1 text-xs font-semibold text-emerald-700"><TrendingUp className="h-4 w-4" />14.8%</span></div><div className="mt-7 flex h-24 items-end gap-2">{[32, 44, 39, 56, 48, 66, 61, 78, 72, 94].map((height, index) => <div key={index} className={`flex-1 ${index === 9 ? 'bg-violet-600' : 'bg-violet-100'}`} style={{ height: `${height}%` }} />)}</div></div><SectionHeading title="Recent system activity" /><div className="border border-slate-200 bg-white p-4 shadow-sm"><p className="flex gap-3 text-sm"><Building2 className="h-4 w-4 shrink-0 text-blue-600" /><span><strong>New cooperative registered</strong><span className="block text-xs text-slate-500">Madurai Services Cooperative · 3h ago</span></span></p></div></div></div></DashboardShell>;
};

export { CustomerDashboard, ApplicantDashboard, WorkerDashboard, CoopOfficerDashboard, FedAdminDashboard };
